def level=(value)
  if value < 1 || value > GameData::GrowthRate.max_level
    raise ArgumentError.new(_INTL("The level number ({1}) is invalid.", value))
  end
  @exp = growth_rate.minimum_exp_for_level(value)
  @level = value
end

def form=(value)
  oldForm = @form
  @form = value
  @ability = nil
  MultipleForms.call("onSetForm", self, value, oldForm)
  calc_stats
  $player&.pokedex&.register(self)
end

def hp=(value)
  @hp = value.clamp(0, @totalhp)
  heal_status if @hp == 0
  @ready_to_evolve = false if @hp == 0
end

def heal_status
  return if egg?
  @status      = :NONE
  @statusCount = 0
end

def item=(value)
  return if value && !GameData::Item.exists?(value)
  @item = (value) ? GameData::Item.get(value).id : value
end

def calc_stats
  base_stats = self.baseStats
  this_level = self.level
  this_IV    = self.calcIV
  # Format stat multipliers due to nature
  nature_mod = {}
  GameData::Stat.each_main { |s| nature_mod[s.id] = 100 }
  this_nature = self.nature_for_stats
  if this_nature
    this_nature.stat_changes.each { |change| nature_mod[change[0]] += change[1] }
  end
  # Calculate stats
  stats = {}
  GameData::Stat.each_main do |s|
    if s.id == :HP
      stats[s.id] = calcHP(base_stats[s.id], this_level, this_IV[s.id], @ev[s.id])
    else
      stats[s.id] = calcStat(base_stats[s.id], this_level, this_IV[s.id], @ev[s.id], nature_mod[s.id])
    end
  end
  hp_difference = stats[:HP] - @totalhp
  @totalhp = stats[:HP]
  self.hp = [@hp + hp_difference, 1].max if @hp > 0 || hp_difference > 0
  @attack  = stats[:ATTACK]
  @defense = stats[:DEFENSE]
  @spatk   = stats[:SPECIAL_ATTACK]
  @spdef   = stats[:SPECIAL_DEFENSE]
  @speed   = stats[:SPEED]
end

alias __shadow_hpeq hp= unless method_defined?(:__shadow_hpeq)
def hp=(value)
  __shadow_hpeq(value)
  @hyper_mode = false if @hp <= 0
end

def level=(value)
  @level = value
  @pokemon.level = value if @pokemon
end

def form=(value)
  @form = value
  @pokemon.form = value if @pokemon
end

def hp=(value)
  @hp = value.to_i
  @pokemon.hp = value.to_i if @pokemon
end

def status=(value)
  @effects[PBEffects::Truant] = false if @status == :SLEEP && value != :SLEEP
  @effects[PBEffects::Toxic]  = 0 if value != :POISON || self.statusCount == 0
  @status = value
  @pokemon.status = value if @pokemon
  self.statusCount = 0 if value != :POISON && value != :SLEEP
  @battle.scene.pbRefreshOne(@index)
end

def statusCount=(value)
  @statusCount = value
  @pokemon.statusCount = value if @pokemon
  @battle.scene.pbRefreshOne(@index)
end

def item=(value)
  new_item = GameData::Item.try_get(value)
  @item_id = (new_item) ? new_item.id : nil
  @pokemon.item = @item_id if @pokemon
end

def pbInitPokemon(pkmn, idxParty)
  raise _INTL("An egg can't be an active Pokémon.") if pkmn.egg?
  @name         = pkmn.name
  @species      = pkmn.species
  @form         = pkmn.form
  @level        = pkmn.level
  @hp           = pkmn.hp
  @totalhp      = pkmn.totalhp
  @types        = pkmn.types
  @ability_id   = pkmn.ability_id
  @item_id      = pkmn.item_id
  @attack       = pkmn.attack
  @defense      = pkmn.defense
  @spatk        = pkmn.spatk
  @spdef        = pkmn.spdef
  @speed        = pkmn.speed
  @status       = pkmn.status
  @statusCount  = pkmn.statusCount
  @pokemon      = pkmn
  @pokemonIndex = idxParty
  @participants = []   # Participants earn Exp. if this battler is defeated
  @moves        = []
  pkmn.moves.each_with_index do |m, i|
    @moves[i] = Battle::Move.from_pokemon_move(@battle, m)
  end
end

def initialize(scene, p1, p2, player, opponent)
  if p1.length == 0
    raise ArgumentError.new(_INTL("Party 1 has no Pokémon."))
  elsif p2.length == 0
    raise ArgumentError.new(_INTL("Party 2 has no Pokémon."))
  end
  @scene             = scene
  @peer              = Peer.new
  @field             = ActiveField.new    # Whole field (gravity/rooms)
  @sides             = [ActiveSide.new,   # Player's side
                        ActiveSide.new]   # Foe's side
  @positions         = []                 # Battler positions
  @battlers          = []
  @sideSizes         = [1, 1]   # Single battle, 1v1
  @backdrop          = ""
  @backdropBase      = nil
  @time              = 0
  @environment       = :None   # e.g. Tall grass, cave, still water
  @turnCount         = 0
  @decision          = 0
  @caughtPokemon     = []
  player   = [player] if !player.nil? && !player.is_a?(Array)
  opponent = [opponent] if !opponent.nil? && !opponent.is_a?(Array)
  @player            = player     # Array of Player/NPCTrainer objects, or nil
  @opponent          = opponent   # Array of NPCTrainer objects, or nil
  @items             = nil
  @ally_items        = nil        # Array of items held by ally. This is just used for Mega Evolution for now.
  @party1            = p1
  @party2            = p2
  @party1order       = Array.new(@party1.length) { |i| i }
  @party2order       = Array.new(@party2.length) { |i| i }
  @party1starts      = [0]
  @party2starts      = [0]
  @internalBattle    = true
  @debug             = false
  @canRun            = true
  @canLose           = false
  @canSwitch         = true
  @switchStyle       = true
  @showAnims         = true
  @controlPlayer     = false
  @expGain           = true
  @moneyGain         = true
  @disablePokeBalls  = false
  @sendToBoxes       = 1
  @rules             = {}
  @priority          = []
  @priorityTrickRoom = false
  @choices           = []
  @megaEvolution     = [
    [-1] * (@player ? @player.length : 1),
    [-1] * (@opponent ? @opponent.length : 1)
  ]
  @initialItems      = [
    Array.new(@party1.length) { |i| (@party1[i]) ? @party1[i].item_id : nil },
    Array.new(@party2.length) { |i| (@party2[i]) ? @party2[i].item_id : nil }
  ]
  @recycleItems      = [Array.new(@party1.length, nil),   Array.new(@party2.length, nil)]
  @belch             = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @battleBond        = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @corrosiveGas      = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @usedInBattle      = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @successStates     = []
  @lastMoveUsed      = nil
  @lastMoveUser      = -1
  @switching         = false
  @futureSight       = false
  @command_phase     = false
  @endOfRound        = false
  @moldBreaker       = false
  @runCommand        = 0
  @nextPickupUse     = 0
  @struggle          = Move::Struggle.new(self, nil)
  @mega_rings        = []
  GameData::Item.each { |item| @mega_rings.push(item.id) if item.has_flag?("MegaRing") }
  @battleAI          = AI.new(self)
end

def initialize(battle, move)
  @battle        = battle
  @realMove      = move
  @id            = move.id
  @name          = move.name   # Get the move's name
  # Get data on the move
  @function_code = move.function_code
  @power         = move.power
  @type          = move.type
  @category      = move.category
  @accuracy      = move.accuracy
  @pp            = move.pp   # Can be changed with Mimic/Transform
  @target        = move.target
  @priority      = move.priority
  @flags         = move.flags.clone
  @addlEffect    = move.effect_chance
  @powerBoost    = false   # For Aerilate, Pixilate, Refrigerate, Galvanize
  @snatched      = false
end
